def count_passing_ways(n: int, m: int) -> int:
    MOD = 10**9 + 7
    dp = [[0] * n for _ in range(m + 1)]
    dp[0][0] = 1

    for k in range(1, m + 1):
        for i in range(n):
            dp[k][i] = (dp[k - 1][(i - 1) % n] + dp[k - 1][(i + 1) % n]) % MOD

    return dp[m][0]

def max_energy(beads):
    def merge_energy(a, b, c):
        return a * b * c

    n = len(beads)
    beads = beads * 2  # Duplicate the list to handle the circular nature
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j % n] = max(
                dp[i][k % n] + dp[(k + 1) % n][j % n] + merge_energy(beads[i], beads[k % n], beads[j % n])
                for k in range(i, j)
            )

    return max(dp[i][(i + n - 1) % n] for i in range(n))

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n + 1):
        coeff = coeffs[i]
        degree = n - i

        if coeff == 0:
            continue

        sign = '+' if coeff > 0 else '-'
        abs_coeff = abs(coeff)

        if abs_coeff == 1 and degree != 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        if not terms:
            terms.append(f'{coeff_str}{var_str}' if coeff_str else f'{sign}{var_str}')
        else:
            terms.append(f'{sign}{coeff_str}{var_str}' if coeff_str else f'{sign}{var_str}')

    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    # Check if the lengths of encoded and original are the same
    if len(encoded) != len(original):
        return "Failed"

    # Create a mapping from encoded to original characters
    mapping = {}
    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            # If there's a contradiction in the mapping, return "Failed"
            if mapping[enc_char] != orig_char:
                return "Failed"
        else:
            mapping[enc_char] = orig_char

    # Check if all characters in the message are in the mapping
    for char in message:
        if char not in mapping:
            return "Failed"

    # Decode the message using the mapping
    decoded_message = ''.join(mapping[char] for char in message)

    return decoded_message

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]

    count = 1  # The sequence itself is a valid sequence

    for next_num in range(1, last // 2 + 1):
        count += count_sequences(n, next_num, memo)

    memo[last] = count
    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    if A == B:
        return 0

    queue = deque([(A, 0)])  # queue stores (current_string, current_step)
    visited = set([A])  # keep track of visited strings to avoid cycles

    while queue:
        current_string, current_step = queue.popleft()

        if current_step > 10:  # limit the search to a maximum of 10 steps
            break

        for src, tgt in rules:
            start = 0
            while start <= len(current_string) - len(src):
                pos = current_string.find(src, start)
                if pos == -1:
                    break
                new_string = current_string[:pos] + tgt + current_string[pos + len(src):]
                if new_string == B:
                    return current_step + 1
                if new_string not in visited:
                    visited.add(new_string)
                    queue.append((new_string, current_step + 1))
                start = pos + 1

    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Convert the number to a string to easily manipulate digits
    original_str = str(n)
    digits = set('0123456789')

    # Create a transformation map based on the rules
    transform_map = defaultdict(list)
    for x, y in rules:
        transform_map[str(x)].append(str(y))

    # BFS to find all unique numbers
    queue = deque([original_str])
    visited = set([original_str])

    while queue:
        current = queue.popleft()

        # Try transforming each digit
        for i in range(len(current)):
            if current[i] not in transform_map:
                continue
            for new_digit in transform_map[current[i]]:
                new_number_str = current[:i] + new_digit + current[i+1:]
                if new_number_str not in visited:
                    visited.add(new_number_str)
                    queue.append(new_number_str)

    # Convert all visited strings back to integers and return the count of unique numbers
    unique_numbers = {int(num) for num in visited}
    return len(unique_numbers)

