def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for participant, participant_statements in statements.items():
        for statement in participant_statements:
            if statement in days_of_week:
                continue
            elif statement == f"I am guilty.":
                if (participant == scenario and participant not in liar_count) or (participant != scenario and participant in liar_count):
                    continue
                else:
                    return False
            elif statement == f"I am not guilty.":
                if (participant != scenario and participant not in liar_count) or (participant == scenario and participant in liar_count):
                    continue
                else:
                    return False
            elif f"{scenario} is guilty." in statement:
                if (participant not in liar_count and participant != scenario) or (participant in liar_count and participant == scenario):
                    continue
                else:
                    return False
            elif f"{scenario} is not guilty." in statement:
                if (participant in liar_count and participant != scenario) or (participant not in liar_count and participant == scenario):
                    continue
                else:
                    return False
    return True

def calculate_score(system: int, points: str) -> list:
    game_scores = []
    player_score = 0
    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1

        # Check if the game is finished
        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            game_scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    # If the sequence ends in the middle of a game, add the current score
    if player_score > 0 or opponent_score > 0:
        game_scores.append(f"{player_score}:{opponent_score}")

    return game_scores

