def jinjin_savings_plan(budgets: List[int]) -> int:
    pocket_money_per_month = 300
    monthly_savings = 100
    total_savings = 0

    for month in range(12):
        remaining_money = pocket_money_per_month - budgets[month]
        if remaining_money < 0:
            return -(month + 1)
        savings = (remaining_money // monthly_savings) * monthly_savings
        total_savings += savings

    # Apply 20% interest at the end of the year
    total_savings += total_savings * 0.20
    return int(total_savings)

def hanoi_double_iterative(n: int) -> int:
    if n == 0:
        return 0
    moves = 0
    for i in range(1, n + 1):
        moves = 3 * moves + 2
    return moves
